// Generated by @canonical/summon-component:react v0.43.0

import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import Peek from "./Peek.js";

/**
 * The selector the stylesheet hides a peek that shows nothing by (the SSR
 * test reads the rule in the stylesheet).
 */
const EMPTY_PEEK = ".ds.peek:not(:has(> :not([hidden])))";

describe("Peek", () => {
  it("is a manual popover dialog named by its hidden label", () => {
    render(
      <Peek anchor="--entity-chip-a" label="Preview of Button">
        <a href="#button">Open Button</a>
      </Peek>,
    );
    const dialog = screen.getByRole("dialog", { hidden: true });
    const label = dialog.getAttribute("aria-labelledby") ?? "";
    expect(document.getElementById(label)?.textContent).toBe(
      "Preview of Button",
    );
    expect(dialog.getAttribute("popover")).toBe("manual");
    expect(dialog.style.getPropertyValue("position-anchor")).toBe(
      "--entity-chip-a",
    );
    expect(dialog.querySelector("a[href]")?.textContent).toBe("Open Button");
  });

  it("applies custom className and passes native props through", () => {
    render(
      <Peek
        anchor="--entity-chip-b"
        className="custom-class"
        data-testid="peek"
        label="Preview"
        style={{ zIndex: 1 }}
      >
        Card
      </Peek>,
    );
    const peek = screen.getByTestId("peek");
    expect(peek.className).toBe("ds peek custom-class");
    expect(peek.style.zIndex).toBe("1");
  });

  it("is not displayed while it shows nothing, and is once it does", () => {
    const { rerender } = render(
      <Peek anchor="--entity-chip-c" data-testid="peek" label="Preview">
        {null}
      </Peek>,
    );
    const peek = screen.getByTestId("peek");
    expect(peek.matches(EMPTY_PEEK)).toBe(true);
    rerender(
      <Peek anchor="--entity-chip-c" data-testid="peek" label="Preview">
        <p>Card</p>
      </Peek>,
    );
    expect(peek.matches(EMPTY_PEEK)).toBe(false);
  });
});
